// Vendored from the Agentic Owners policy core; see README.md in this
// directory. Precedence must stay identical to the source's.

import type { AgenticOwnersPathRule } from "./types.js";

/**
 * Winners a root `global_overrides` entry must not change: owner-clearing
 * carve-outs, hard gates, and notify rules.
 */
export function blocksGlobalOverride(rule: AgenticOwnersPathRule): boolean {
  return (
    rule.globalExclusion === true ||
    rule.alwaysApprove ||
    rule.mode === "hard" ||
    rule.humanReviewRequired ||
    rule.mode === "notify"
  );
}

function unionOwners(lists: readonly (readonly string[])[]): string[] {
  return [...new Set(lists.flat())];
}

function selfReviewOwners(rule: AgenticOwnersPathRule): {
  readonly selfReviewTeams: readonly string[];
  readonly selfReviewUsers: readonly string[];
} {
  return {
    selfReviewTeams: rule.selfReviewTeams ?? rule.teams,
    selfReviewUsers: rule.selfReviewUsers ?? rule.users,
  };
}

/**
 * Let override owners clear a file the winner owns by self-review. The
 * winner's owners, reviewers, and lane are unchanged, so an author outside the
 * override needs exactly the review they would without it. The winner's
 * owners self-review only when the winner sets `self_review`. An override
 * whose `self_review` a policy edit withheld grants nothing.
 */
export function mergeGlobalOverride(
  winner: AgenticOwnersPathRule,
  overrides: readonly AgenticOwnersPathRule[],
): AgenticOwnersPathRule {
  const granting = overrides.filter((rule) => rule.selfReview);
  if (granting.length === 0) {
    return winner;
  }
  const selfReviewers = winner.selfReview ? [winner, ...granting] : granting;
  return {
    ...winner,
    selfReview: true,
    selfReviewTeams: unionOwners(
      selfReviewers.map((rule) => selfReviewOwners(rule).selfReviewTeams),
    ),
    selfReviewUsers: unionOwners(
      selfReviewers.map((rule) => selfReviewOwners(rule).selfReviewUsers),
    ),
  };
}
